create table choferes (nombre text primary key);
insert into choferes values ('Ana'), ('Beto'), ('Carla'), ('Diego');
create table zonas (zona text primary key);
insert into zonas values ('Norte'), ('Sur'), ('Oeste');
-- «atiende» solo guarda las parejas (chofer, zona) que son verdad
create table atiende (
  chofer text references choferes,
  zona   text references zonas,
  primary key (chofer, zona)
);
insert into atiende values
 ('Ana','Norte'), ('Ana','Sur'), ('Beto','Sur'), ('Carla','Oeste'), ('Diego','Norte');

